// ---- Chunk: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: ChunkBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Chunk is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct ChunkBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    ChunkBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Chunk> slot = main.Alloc<Chunk>();
        root_ref = slot.ref;
    }
    ~ChunkBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    ChunkBuilder( const ChunkBuilder & ) = delete;
    ChunkBuilder & operator=( const ChunkBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Chunk * GetRoot() { return arena.locked ? NULL : (Chunk *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Chunk * AsConst() const { return (const Chunk *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool ChunkBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Chunk & root = *(const Chunk *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = ChunkPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t total = TableAlignUp64( (int64_t) sizeof( Chunk ) ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( (int64_t) sizeof( Chunk ) );
    Chunk * destination = new ( packed ) Chunk; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !ChunkPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Chunk on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// ChunkNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides.
inline int64_t ChunkNodeStorage( uint64_t type_id, int64_t length )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: return TableAlignUp64( (int64_t) sizeof( Chunk ) ); // Chunk
        default: break;
    }
    return -1;
}

// ChunkNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void ChunkNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: { Chunk * node = new ( at ) Chunk; ChunkReset( *node ); break; } // Chunk
        default: break;
    }
}

// ChunkNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t ChunkNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: return (uint32_t) worker.Alloc<Chunk>().ref.value; // Chunk
        default: break;
    }
    return 0;
}

// ChunkNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void ChunkNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: ChunkLoadBody( r, nodes, *(Chunk *) at ); break; // Chunk
        default: break;
    }
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool ChunkNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Chunk & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return ChunkNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t ChunkMeasureWire( const Ctx & ctx, const Chunk & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( ChunkNumberFrom( ctx, numbering, root ) )
    {
        bytes = ChunkMeasureBody( ctx, root );
        if ( bytes >= 0 )
        {
            int64_t table = TableNodeTableMeasure( ctx, numbering );
            bytes = table < 0 ? -1 : bytes + table;
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t ChunkSaveWire( const Ctx & ctx, const Chunk & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !ChunkNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    // the root's own fields, then the node table's fields, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = ChunkSaveBodyFields( ctx, numbering, w, root ) && TableNodeTableSave( ctx, w, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok ) { return -1; }
    w.put16( 0 );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == ChunkMeasure( root )
}

inline int64_t ChunkMeasure( const Chunk * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return ChunkMeasureWire( ctx, *root, allocator );
}

inline int64_t ChunkSave( const Chunk * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return ChunkSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t ChunkMeasure( const ChunkBuilder & builder )
{
    if ( builder.region != NULL ) { return ChunkMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return ChunkMeasureWire( ctx, *(const Chunk *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t ChunkSave( const ChunkBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return ChunkSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return ChunkSaveWire( ctx, *(const Chunk *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// ChunkLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t ChunkLoadMeasure( const uint8_t * wire, int64_t wire_bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored );
    int64_t data = TableAlignUp64( (int64_t) sizeof( Chunk ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = ChunkNodeStorage( type_id, length );
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// ChunkLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Chunk * ChunkLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Chunk ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    int64_t data = TableAlignUp64( (int64_t) sizeof( Chunk ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = ChunkNodeStorage( type_id, length );
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0xcf4368dcf951e082ull;
    Chunk * root = new ( region ) Chunk; // lifetime only: LoadBody's first act is ChunkReset
    ChunkReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Chunk ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = ChunkNodeStorage( type_id, length );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                ChunkNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                ChunkNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out );
    ChunkLoadBody( r, nodes, *root );
    return root;
}

// ChunkLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool ChunkLoadBuilder( ChunkBuilder & builder, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    Chunk * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0xcf4368dcf951e082ull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = ChunkNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                ChunkNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out );
    bool ok = ChunkLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- Feed: the variable-length life (docs/SPEC-TABLES.md §2, §6, §9) ----
//
// MUTABLE: FeedBuilder — allocate nodes, wire them together, then Lock.
// CONST:   one packed region, root at its base. Lock produces it and Load
//          produces it, so a locked structure and a loaded one are the
//          SAME representation with one view API. There is no unlock:
//          re-editing means loading the const form into a fresh builder.
// Feed is never held by value — a file-format-scale structure is a region
// and a root pointer, not a struct you copy.

struct FeedBuilder
{
    TableArena arena;
    TableWorker main;      // the calling thread's allocation front
    TableRef root_ref;
    uint8_t * region = NULL; // the packed const form, produced by Lock()
    int64_t region_bytes = 0;

    // THE ALLOCATOR IS THE BUILDER'S, and everything this structure ever
    // allocates goes through it: the arena's segments, Lock's identity map,
    // the packed region, the wire walks' numbering, and the tool path's node
    // directory. Name your own and a profiler sees every byte under it.
    FeedBuilder( TableAllocator allocator = TableDefaultAllocator() )
    {
        TableArenaInit( arena, allocator );
        main.arena = &arena;
        TableSlot<Feed> slot = main.Alloc<Feed>();
        root_ref = slot.ref;
    }
    ~FeedBuilder() { TableArenaShutdown( arena ); arena.allocator.free( arena.allocator.context, region ); }
    FeedBuilder( const FeedBuilder & ) = delete;
    FeedBuilder & operator=( const FeedBuilder & ) = delete;

    // Alloc a node in THIS thread's slab: no lock, no atomic per node.
    // The result is usable both as the node pointer and as the reference
    // to store in a pointer field.
    template <typename T> TableSlot<T> Alloc() { return main.Alloc<T>(); }
    // a BYTE BUFFER's node of exactly `length` bytes (docs/SPEC-TABLES.md §2.5):
    // the bytes to write through, and the reference to store in a *bytes
    // or *string slot; a blob past a slab takes a span of its own
    TableBytesSlot AllocBytes( int64_t length ) { return main.AllocBytes( length ); }
    TableStringSlot AllocString( int64_t length ) { return main.AllocString( length ); }
    // one worker per thread; allocate on your own, and synchronize your own
    // writes to nodes another worker allocated
    TableWorker Worker() { TableWorker worker; worker.arena = &arena; return worker; }

    // GetRoot/AsConst, not Root/Const: a member function hides the type
    // name it shares, and `table Root` is this spec's own canonical
    // example. The checker refuses a table named after any member here,
    // so the remaining spellings cannot collide either.
    Feed * GetRoot() { return arena.locked ? NULL : (Feed *) TableArenaAt( arena, (uint32_t) root_ref.value ); }
    bool Locked() const { return arena.locked; }
    const Feed * AsConst() const { return (const Feed *) region; }
    const uint8_t * Region() const { return region; }
    int64_t RegionBytes() const { return region_bytes; }

    // Lock is ONE WAY and it is the compaction: the segmented arena becomes
    // one exact-packed region with zero slack, references rewritten
    // self-relative, and the mutable life released. Single-threaded: call
    // it after the workers have joined.
    bool Lock();
};

inline bool FeedBuilder::Lock()
{
    if ( arena.locked ) { return region != NULL; }
    if ( root_ref.null() ) { return false; }
    TableArenaCtx ctx = { &arena };
    const Feed & root = *(const Feed *) TableArenaAt( arena, (uint32_t) root_ref.value );
    // The ROOT takes the map's first entry: it is packed at offset 0, and its
    // descent is open for the whole walk (docs/SPEC-TABLES.md §3.1).
    TablePackMap seen;
    TablePackMapInit( seen, arena.allocator );
    bool root_taken = false;
    int64_t root_slot = 0;
    int64_t below = -1;
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) != NULL )
    {
        below = FeedPackMeasure( ctx, seen, root );
    }
    if ( below < 0 ) { TablePackMapShutdown( seen ); return false; } // a data cycle, named at the reference that closes it
    int64_t total = TableAlignUp64( (int64_t) sizeof( Feed ) ) + below;
    // the AUTHORING path may allocate (§6.5), and it does so through the
    // builder's own pair. The region comes back ZEROED, which is the
    // allocator's contract: a packed region carries node padding.
    uint8_t * packed = (uint8_t *) arena.allocator.alloc( arena.allocator.context, total );
    if ( packed == NULL ) { TablePackMapShutdown( seen ); return false; }
    int64_t used = TableAlignUp64( (int64_t) sizeof( Feed ) );
    Feed * destination = new ( packed ) Feed; // lifetime only: the Pack below memcpy's the whole node over it
    // The pack walk RE-DERIVES the same numbering rather than carrying the
    // measure's — nothing passes between them, which is what makes
    // `used == total` below a real check and not a tautology (§3.1). The
    // map keeps the capacity the measure paid for, so the second walk
    // rehashes nothing.
    TablePackMapReset( seen );
    if ( TablePackMapReach( seen, (const void *) &root, 0, root_taken, root_slot ) == NULL ||
         !FeedPack( ctx, seen, root, *destination, packed, total, used ) || used != total )
    {
        TablePackMapShutdown( seen );
        arena.allocator.free( arena.allocator.context, packed );
        return false;
    }
    TablePackMapShutdown( seen );
    region = packed;
    region_bytes = total;
    arena.locked = true; // MONOTONIC: there is no unlock
    TableArenaShutdown( arena );
    return true;
}

// ---- Feed on the wire: the FLAT NODE TABLE (docs/SPEC-TABLES.md §3.1) ----
//
// A pointered save writes every reachable node ONCE, into a node table under
// the reserved id 0xFFFF, and a pointer field rides as a u32 INDEX into it
// under kind 17. No pointer edge is a nesting level, so a chain's length is
// not a depth and two references to one node are one node.

// FeedNodeStorage: the region bytes one record commands, or -1 for a type id
// this build cannot name — which keeps its index and reads null. A BYTE
// BUFFER's record commands its header and its bytes (docs/SPEC-TABLES.md §2.5),
// which is the one answer the record's LENGTH decides.
inline int64_t FeedNodeStorage( uint64_t type_id, int64_t length )
{
    (void) length; // no byte buffer below this root: every node's storage is its type's
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: return TableAlignUp64( (int64_t) sizeof( Chunk ) ); // Chunk
        default: break;
    }
    return -1;
}

// FeedNodePlace: start one record's node's lifetime in the storage pass one
// reserved for it, holding exactly the declared defaults — a byte buffer's
// header holds its length, and its bytes come in pass two.
inline void FeedNodePlace( uint64_t type_id, uint8_t * at, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: { Chunk * node = new ( at ) Chunk; ChunkReset( *node ); break; } // Chunk
        default: break;
    }
}

// FeedNodeAlloc: the TOOL's path — one record's node in the builder's arena.
// Zero is the arena's null, and it is also what a type id this build cannot
// name answers.
inline uint32_t FeedNodeAlloc( uint64_t type_id, TableWorker & worker, int64_t length )
{
    (void) length;
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: return (uint32_t) worker.Alloc<Chunk>().ref.value; // Chunk
        default: break;
    }
    return 0;
}

// FeedNodeBody: PASS TWO's half — decode one record's body into the storage it
// already owns.
inline void FeedNodeBody( uint64_t type_id, TableReader & r, const TableNodeMap & nodes, uint8_t * at )
{
    switch ( type_id )
    {
        case 0xcf4368dcf951e082ull: ChunkLoadBody( r, nodes, *(Chunk *) at ); break; // Chunk
        default: break;
    }
}

// The numbering both wire walks derive, and NEITHER CARRIES THE OTHER'S: the
// root takes index 1 and its entry stays open for the whole walk, so a
// reference back at it is the cycle it is (§3.1).
template <typename Ctx>
inline bool FeedNumberFrom( const Ctx & ctx, TableNumbering & numbering, const Feed & root )
{
    bool taken = false;
    int64_t slot = 0;
    if ( TablePackMapReach( numbering.seen, (const void *) &root, (int64_t) kTableNodeIndexRoot, taken, slot ) == NULL ) { return false; }
    return FeedNumber( ctx, numbering, root );
}

template <typename Ctx>
inline int64_t FeedMeasureWire( const Ctx & ctx, const Feed & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    int64_t bytes = -1;
    if ( FeedNumberFrom( ctx, numbering, root ) )
    {
        bytes = FeedMeasureBody( ctx, root );
        if ( bytes >= 0 )
        {
            int64_t table = TableNodeTableMeasure( ctx, numbering );
            bytes = table < 0 ? -1 : bytes + table;
        }
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

template <typename Ctx>
inline int64_t FeedSaveWire( const Ctx & ctx, const Feed & root, uint8_t * buffer, int64_t capacity, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    if ( !FeedNumberFrom( ctx, numbering, root ) ) { TableNumberingShutdown( numbering ); return -1; }
    TableWriter w( buffer, capacity );
    // the root's own fields, then the node table's fields, then the
    // terminator: a reader that gives up inside the table has already
    // decoded the ROOT'S OWN FIELDS (§3.1)
    bool ok = FeedSaveBodyFields( ctx, numbering, w, root ) && TableNodeTableSave( ctx, w, numbering );
    TableNumberingShutdown( numbering );
    if ( !ok ) { return -1; }
    w.put16( 0 );
    if ( w.overflow ) { return -1; } // the caller's buffer was too small
    return w.offset; // == FeedMeasure( root )
}

inline int64_t FeedMeasure( const Feed * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FeedMeasureWire( ctx, *root, allocator );
}

inline int64_t FeedSave( const Feed * root, uint8_t * buffer, int64_t capacity, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FeedSaveWire( ctx, *root, buffer, capacity, allocator );
}

inline int64_t FeedMeasure( const FeedBuilder & builder )
{
    if ( builder.region != NULL ) { return FeedMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedMeasureWire( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline int64_t FeedSave( const FeedBuilder & builder, uint8_t * buffer, int64_t capacity )
{
    if ( builder.region != NULL ) { return FeedSave( builder.AsConst(), buffer, capacity, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedSaveWire( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), buffer, capacity, builder.arena.allocator );
}

// FeedLoadMeasure: the exact region bytes a wire buffer will need, and it is
// ONE SCAN — a record's type id gives its storage size, its length gives the
// next record — reading no field value at all, so the caller owns the
// allocation and can refuse a number it did not expect (§6.5).
//
// It reports the DATA bytes and the ATTRIBUTION bytes separately, because the
// attribution is the wire's numbering made resident (§6.3) and a caller may
// release it once Load returns. The answer is their sum.
inline int64_t FeedLoadMeasure( const uint8_t * wire, int64_t wire_bytes, int64_t * attribution_bytes = NULL )
{
    TableReport ignored;
    TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &ignored );
    int64_t data = TableAlignUp64( (int64_t) sizeof( Feed ) );
    int64_t records = 0;
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    while ( TableNodeScanNext( scan, type_id, body, length ) )
    {
        records++;
        int64_t storage = FeedNodeStorage( type_id, length );
        if ( storage > 0 ) { data += storage; } // a type id this build cannot name commands none
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( attribution_bytes != NULL ) { *attribution_bytes = attribution; }
    return data + attribution;
}

// FeedLoad: decode the tolerant wire into the caller's exact-sized region and
// return the root. LOAD IS A SCAN, and that is the whole of its bound: it
// follows no reference, so there is no depth cap, no visited set and no
// ordering rule on the indices. Partial results are kept, as everywhere on
// this wire — the report says what happened. NULL means the CALLER's buffer
// was wrong.
inline const Feed * FeedLoad( uint8_t * region, int64_t region_bytes, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    if ( region == NULL || region_bytes < (int64_t) sizeof( Feed ) ) { out->malformed = true; return NULL; }
    if ( ( ( (uintptr_t) region ) & ( kTableAlign - 1 ) ) != 0 ) { out->malformed = true; return NULL; }
    memset( region, 0, (size_t) region_bytes );
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;

    // the record count and the data bytes, from the FRAMING alone
    int64_t data = TableAlignUp64( (int64_t) sizeof( Feed ) );
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            records++;
            int64_t storage = FeedNodeStorage( type_id, length );
            if ( storage > 0 ) { data += storage; }
        }
    }
    int64_t attribution = ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry );
    if ( data + attribution > region_bytes ) { out->malformed = true; return NULL; }

    TableNodeMap nodes;
    nodes.base = region;
    nodes.entries = (const TableNodeDirEntry *) ( region + data );
    nodes.count = records + 1;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) ( region + data );
    directory[0].offset = 0; // position 0 is the ROOT, at offset 0 (§6.3)
    directory[0].type_id = 0x3a8fe3852a245245ull;
    Feed * root = new ( region ) Feed; // lifetime only: LoadBody's first act is FeedReset
    FeedReset( *root );

    // PASS ONE: fill the numbering from the framing, so that an index
    // resolves whichever way it points. It reads no body.
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t used = TableAlignUp64( (int64_t) sizeof( Feed ) );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            int64_t storage = FeedNodeStorage( type_id, length );
            if ( storage <= 0 )
            {
                // a record whose type id this build cannot name KEEPS ITS
                // INDEX, is counted once here and not once per pointer, and
                // every reference to it reads null (§3.1)
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
                directory[k + 1].type_id = type_id;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) used;
                directory[k + 1].type_id = type_id;
                FeedNodePlace( type_id, region + used, length );
                used += storage;
            }
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        // the table is whole or it is nothing: a scan that failed counts
        // malformed and NOT the unknowns it met on the way, because the
        // numbering they belonged to does not exist (§3.1)
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }

    // PASS TWO: decode each body into its own storage. A forward index
    // resolves without scratch, because pass one already placed every node.
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                FeedNodeBody( type_id, sub, nodes, region + directory[k + 1].offset );
            }
            k++;
        }
    }

    // and the ROOT's own body last, so every index it carries resolves
    // against a numbering already known good or already known bad
    TableReader r( wire, wire_bytes, out );
    FeedLoadBody( r, nodes, *root );
    return root;
}

// FeedLoadBuilder: the TOOL's path — the same tolerant decode into a fresh
// builder, so loaded data can be edited and locked again. The numbering is
// the same one; what differs is where a node lives and therefore what a
// resolved slot holds — an arena offset here, a self-relative delta there.
inline bool FeedLoadBuilder( FeedBuilder & builder, const uint8_t * wire, int64_t wire_bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * out = report != NULL ? report : &ignored;
    Feed * root = builder.GetRoot();
    if ( root == NULL ) { out->malformed = true; return false; }
    uint64_t type_id = 0;
    const uint8_t * body = NULL;
    int64_t length = 0;
    int64_t records = 0;
    {
        TableReport counting;
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, &counting );
        while ( TableNodeScanNext( scan, type_id, body, length ) ) { records++; }
    }
    // the AUTHORING side may allocate (§6.5), and this is the tool's path.
    // It goes through the builder's own pair, like everything else the
    // builder reaches, and the entries come back zeroed.
    const TableAllocator allocator = builder.arena.allocator;
    TableNodeDirEntry * directory = (TableNodeDirEntry *) allocator.alloc( allocator.context, ( records + 1 ) * (int64_t) sizeof( TableNodeDirEntry ) );
    if ( directory == NULL ) { out->malformed = true; return false; }
    directory[0].offset = (uint64_t) builder.root_ref.value;
    directory[0].type_id = 0x3a8fe3852a245245ull;
    TableNodeMap nodes;
    nodes.base = NULL;
    nodes.entries = directory;
    nodes.count = records + 1;
    nodes.arena = true; // a resolved slot holds the node's ARENA OFFSET here
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        int32_t unknown_records = 0; // counted once the scan is known whole
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            uint32_t at = FeedNodeAlloc( type_id, builder.main, length );
            if ( at == 0 )
            {
                unknown_records++;
                directory[k + 1].offset = kTableNodeAbsent;
            }
            else
            {
                directory[k + 1].offset = (uint64_t) at;
            }
            directory[k + 1].type_id = type_id;
            k++;
        }
        nodes.good = TableNodeScanWhole( scan );
        if ( nodes.good ) { out->unknown += unknown_records; } else { out->malformed = true; }
    }
    if ( nodes.good )
    {
        TableNodeScan scan = TableNodeScanBegin( wire, wire_bytes, out );
        int64_t k = 0;
        while ( TableNodeScanNext( scan, type_id, body, length ) )
        {
            if ( directory[k + 1].offset != kTableNodeAbsent )
            {
                TableReader sub( body, length, out );
                FeedNodeBody( type_id, sub, nodes, TableArenaAt( builder.arena, (uint32_t) directory[k + 1].offset ) );
            }
            k++;
        }
    }
    TableReader r( wire, wire_bytes, out );
    bool ok = FeedLoadBody( r, nodes, *root );
    allocator.free( allocator.context, directory );
    return ok;
}

// ---- the cooked form: point at a cook (docs/SPEC-TABLES.md §7) ----

// HeaderOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// Header IS FIXED-SIZE, so its cook is ONE REGION OF ONE NODE and not a second
// shape (§7): one struct behind the header, at the region's base, which is
// what this returns. There is no graph below it and nothing to resolve.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Header * HeaderOpen( const void * bytes, uint64_t length )
{
    return (const Header *) TableCookOpen( bytes, length, (uint64_t) sizeof( Header ), (uint64_t) alignof( Header ) );
}

// ChunkOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// A REFERENCE INSIDE THE REGION IS DEREFERENCED THROUGH ChunkAt: the slot holds
// the signed self-relative byte delta of §6.3, so a deref is one add and
// needs no base pointer, a whole region relocates by plain memcpy, and a
// delta of zero is null.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Chunk * ChunkOpen( const void * bytes, uint64_t length )
{
    return (const Chunk *) TableCookOpen( bytes, length, (uint64_t) sizeof( Chunk ), (uint64_t) alignof( Chunk ) );
}

// FeedOpen: match the header and POINT. On a match the bytes ARE what this
// build wrote, in this build's layout and this build's byte order, so there
// is nothing to validate and nothing to fix up and the root comes back as it
// lies. On ANY refusal it returns NULL and the caller falls back to a wire
// load, which is the path that carries every version.
//
// It is O(1) IN THE FILE'S SIZE — the header and nothing per node — so a one
// megabyte cook and a one gigabyte cook open in the same time, and a mapped
// file's pages are touched only as they are used. That is a property of
// touching nothing at open rather than a separate mechanism.
//
// A REFERENCE INSIDE THE REGION IS DEREFERENCED THROUGH FeedAt: the slot holds
// the signed self-relative byte delta of §6.3, so a deref is one add and
// needs no base pointer, a whole region relocates by plain memcpy, and a
// delta of zero is null.
//
// There is ONE entry point and no tolerant twin: a build either wrote this
// file or it did not, and the build version is what says which. Validating a
// file whose provenance a person doubts is schema cook-check, offline,
// over the ATTRIBUTION part beside the data — a person's decision, never a
// parameter on a load.
inline const Feed * FeedOpen( const void * bytes, uint64_t length )
{
    return (const Feed *) TableCookOpen( bytes, length, (uint64_t) sizeof( Feed ), (uint64_t) alignof( Feed ) );
}

// ---- the cooked form: WRITE a cook (docs/SPEC-TABLES.md §7.6) ----
//
// The bytes are `schema cook`'s, and the tool stays the reference: the two
// writers are held to one file, byte for byte, in both byte orders. A cook is
// content-addressed by (asset hash, build version), so two writers of one
// instance produce ONE artifact or the pair means nothing.

inline void HeaderCookBody( uint8_t * at, const Header & value, TableByteOrder order );
template <typename Ctx> inline bool ChunkCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Chunk & value, TableByteOrder order );
template <typename Ctx> inline bool FeedCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Feed & value, TableByteOrder order );

inline void HeaderCookBody( uint8_t * at, const Header & value, TableByteOrder order )
{
    table_cook_bytes( at + 0, value.name, value.name_length, 17 );
    table_cook_put( at + 20, (uint64_t) (uint32_t) value.name_length, 4, order );
}

template <typename Ctx> inline bool ChunkCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Chunk & value, TableByteOrder order )
{
    table_cook_bytes( at + 0, value.data, value.data_length, 8 );
    table_cook_put( at + 8, (uint64_t) (uint32_t) value.data_length, 4, order );
    if ( !table_cook_ref( region, at + 16, (const void *) ChunkAt( ctx, value.next ), order ) ) { return false; } // next
    for ( int32_t i = 0; i < 2; i++ ) // links: an array of pointers, every slot
    {
        if ( !table_cook_ref( region, at + 24 + i * 8, (const void *) ChunkAt( ctx, value.links[ i ] ), order ) ) { return false; }
    }
    table_cook_put( at + 40, (uint64_t) (uint32_t) value.links_count, 4, order );
    return true;
}

template <typename Ctx> inline bool FeedCookBody( const Ctx & ctx, const TableCookRegion & region, uint8_t * at, const Feed & value, TableByteOrder order )
{
    table_cook_put( at + 0, (uint64_t) value.id, 4, order );
    {
        table_cook_put( at + 8, (uint64_t) value.frame.type, 1, order ); // the tag; None is the tag alone
        switch ( value.frame.type )
        {
            case FrameType::Header: HeaderCookBody( at + 8 + 8, value.frame.header, order ); break;
            case FrameType::Chunk: if ( !ChunkCookBody( ctx, region, at + 8 + 8, value.frame.chunk, order ) ) { return false; } break;
            default: break; // every byte outside the set arm stays zero
        }
    }
    for ( int32_t i = 0; i < 4; i++ ) // parts: an array of pointers, every slot
    {
        if ( !table_cook_ref( region, at + 64 + i * 8, (const void *) ChunkAt( ctx, value.parts[ i ] ), order ) ) { return false; }
    }
    table_cook_put( at + 96, (uint64_t) (uint32_t) value.parts_count, 4, order );
    for ( int32_t i = 0; i < 2; i++ ) // pair: an array of pointers, every slot
    {
        if ( !table_cook_ref( region, at + 104 + i * 8, (const void *) ChunkAt( ctx, value.pair[ i ] ), order ) ) { return false; }
    }
    return true;
}

// HeaderCookMeasure: the whole cooked file's bytes — the header, the data part
// and the attribution part (docs/SPEC-TABLES.md §7.1). It answers in int64_t
// because a cook's part lengths are 64 bits: the scale this form exists for is
// a catalog, and a 32-bit answer would reimpose the ceiling §3.1 removed.
//
// Header IS FIXED-SIZE, so the answer does not depend on the value: its cook is
// ONE REGION OF ONE NODE (§7) — the record at the region's base, its length
// rounded to the region's alignment, and one directory entry.
inline int64_t HeaderCookMeasure( const Header & value )
{
    (void) value;
    return 104; // 64 header + 24 data + 16 attribution
}

// HeaderCook: write one cooked file for the build this code is compiled into,
// in the byte order the caller names. The bytes are `schema cook`'s, byte for
// byte, and the tool is the reference (§7.6).
//
// THE CALLER OWNS THE BUFFER AND NOTHING IS ALLOCATED: measure, then write.
// A capacity short of the measure writes nothing and returns false, which is
// the same contract HeaderMeasure/HeaderSave has on the wire (§6.1).
//
// EVERY BYTE NO FIELD COVERS IS ZERO (§7.2) — interior padding, the record's
// trailing padding, a string's unused tail, the bytes of a union outside its
// set arm, and the slack the rounded data length leaves. It comes from the one
// memset below rather than from a rule per padding site, and it is what makes
// two cooks of one value ONE artifact (§7).
inline bool HeaderCook( const Header & value, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( out == NULL ) { return false; }
    const uint64_t need = (uint64_t) HeaderCookMeasure( value );
    if ( capacity < need ) { return false; }
    uint8_t * raw = (uint8_t *) out;
    memset( raw, 0, (size_t) need );
    // the HEADER (§7.1), every word a u64 in the order the file is produced in
    table_cook_put( raw + 0, TableCookMagic, 8, order );
    table_cook_put( raw + 8, BuildVersion, 8, order );
    table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
    table_cook_put( raw + 24, 24, 8, order ); // data_length, rounded to the region's alignment
    table_cook_put( raw + 32, 16, 8, order ); // attribution_length: one entry, one node
    table_cook_put( raw + 40, 8, 8, order ); // the region's alignment
    // the two RESERVED words are zero, and the memset already wrote them
    // the DATA part: the region, which for a fixed root is the record at its base
    HeaderCookBody( raw + 64, value, order );
    // the ATTRIBUTION part: the node directory (§6.3), written beside the data
    // for `schema cook-check` — one entry, the root at offset zero, and its type
    // id is the fnv1a64 of the table's name (§3.1)
    table_cook_put( raw + 88, 0, 8, order );
    table_cook_put( raw + 96, 0x75d83fc3f0cfab40ull, 8, order );
    return true;
}

// ChunkCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
inline bool ChunkCookLayout( const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    int64_t offset = 48; // the root, at zero
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            case 0xcf4368dcf951e082ull: size = 48; node_align = 8; break; // Chunk
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// ChunkCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t ChunkCookMeasureFrom( const Ctx & ctx, const Chunk & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( ChunkNumberFrom( ctx, numbering, root ) && ChunkCookLayout( numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// ChunkCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool ChunkCookFrom( const Ctx & ctx, const Chunk & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = ChunkNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && ChunkCookLayout( numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = ChunkCookBody( ctx, region, region.base, root, order );
            for ( int64_t k = 0; ok && k < numbering.count; k++ )
            {
                uint8_t * at = region.base + region.offsets[k + 1];
                const void * node = numbering.entries[k].node;
                switch ( numbering.entries[k].type_id )
                {
                    case 0xcf4368dcf951e082ull: ok = ChunkCookBody( ctx, region, at, *(const Chunk *) node, order ); break; // Chunk
                    default: ok = false; break;
                }
            }
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0xcf4368dcf951e082ull, 8, order ); // the root: fnv1a64( "Chunk" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// ChunkCookMeasure / ChunkCook over a REGION root — a locked builder's AsConst, a
// region ChunkLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t ChunkCookMeasure( const Chunk * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return ChunkCookMeasureFrom( ctx, *root, allocator );
}

inline bool ChunkCook( const Chunk * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return ChunkCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t ChunkCookMeasure( const ChunkBuilder & builder )
{
    if ( builder.region != NULL ) { return ChunkCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return ChunkCookMeasureFrom( ctx, *(const Chunk *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool ChunkCook( const ChunkBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return ChunkCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return ChunkCookFrom( ctx, *(const Chunk *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// FeedCookLayout: the tool's own Layout (docs/SPEC-TABLES.md §7.2) over one
// numbering — the root at zero, then every node in index order at
// align_up( offset, alignof ) for its OWN type, no slack between them, the
// data length rounded to the greatest alignment among them and never below
// eight. The offsets go into the region's table when it has one, and are only
// summed when it does not (a measure). A type id the numbering carries that
// this root cannot name is the two walks disagreeing, and it is refused.
inline bool FeedCookLayout( const TableNumbering & numbering, TableCookRegion & region )
{
    region.numbering = &numbering;
    region.count = numbering.count + 1;
    int64_t offset = 120; // the root, at zero
    int64_t align = 8;
    if ( region.offsets != NULL ) { region.offsets[0] = 0; }
    for ( int64_t k = 0; k < numbering.count; k++ )
    {
        int64_t size = 0;
        int64_t node_align = 0;
        switch ( numbering.entries[k].type_id )
        {
            case 0xcf4368dcf951e082ull: size = 48; node_align = 8; break; // Chunk
            default: return false;
        }
        offset = ( offset + node_align - 1 ) & ~( node_align - 1 );
        if ( region.offsets != NULL ) { region.offsets[k + 1] = offset; }
        offset += size;
        if ( node_align > align ) { align = node_align; }
    }
    region.bytes = ( offset + align - 1 ) & ~( align - 1 );
    region.align = align;
    return true;
}

// FeedCookMeasureFrom: the whole cooked file's bytes for one graph — the header,
// the data part and the attribution part (§7.1). IT DEPENDS ON THE VALUE,
// because the answer is the numbering: the depth-first walk of §3.1 is run
// here and run again by the write, and neither carries the other's (§7.6). A
// data cycle is refused by the walk and answers -1.
template <typename Ctx>
inline int64_t FeedCookMeasureFrom( const Ctx & ctx, const Feed & root, TableAllocator allocator )
{
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    int64_t bytes = -1;
    if ( FeedNumberFrom( ctx, numbering, root ) && FeedCookLayout( numbering, region ) )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        bytes = data_offset + region.bytes + region.count * (int64_t) sizeof( TableNodeDirEntry );
    }
    TableNumberingShutdown( numbering );
    return bytes;
}

// FeedCookFrom: write one cooked file of a pointered graph, in the byte order
// the caller names. The bytes are `schema cook`'s, byte for byte (§7.6).
//
// THE CALLER OWNS THE OUTPUT and nothing is allocated toward it. What is
// allocated is the numbering — the identity map, the entry array and one
// offset per node — through the pair handed in, and released before this
// returns (§6.5, §13.9). A capacity short of the measure writes nothing.
//
// THE HEADER IS WRITTEN LAST. A reference the numbering did not carry is
// found while a body is being written, and a write that refuses there has
// already put bytes in the buffer; with no magic ahead of them, no Open can
// mistake them for a cook.
template <typename Ctx>
inline bool FeedCookFrom( const Ctx & ctx, const Feed & root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator )
{
    if ( out == NULL ) { return false; }
    TableNumbering numbering;
    TableNumberingInit( numbering, allocator );
    TableCookRegion region;
    bool ok = FeedNumberFrom( ctx, numbering, root );
    if ( ok )
    {
        region.offsets = (int64_t *) allocator.alloc( allocator.context, ( numbering.count + 1 ) * (int64_t) sizeof( int64_t ) );
        ok = region.offsets != NULL && FeedCookLayout( numbering, region );
    }
    if ( ok )
    {
        const int64_t data_offset = ( kTableCookHeaderBytes + region.align - 1 ) & ~( region.align - 1 );
        const int64_t attribution = region.count * (int64_t) sizeof( TableNodeDirEntry );
        const int64_t need = data_offset + region.bytes + attribution;
        ok = (uint64_t) need <= capacity;
        if ( ok )
        {
            uint8_t * raw = (uint8_t *) out;
            memset( raw, 0, (size_t) need ); // EVERY BYTE NO FIELD COVERS IS ZERO (§7.2)
            region.base = raw + data_offset;
            // the DATA part: the root at the region's base, then every numbered
            // node at the offset the layout gave it, each through its own writer
            ok = FeedCookBody( ctx, region, region.base, root, order );
            for ( int64_t k = 0; ok && k < numbering.count; k++ )
            {
                uint8_t * at = region.base + region.offsets[k + 1];
                const void * node = numbering.entries[k].node;
                switch ( numbering.entries[k].type_id )
                {
                    case 0xcf4368dcf951e082ull: ok = ChunkCookBody( ctx, region, at, *(const Chunk *) node, order ); break; // Chunk
                    default: ok = false; break;
                }
            }
            // the ATTRIBUTION part: the node directory (§6.3), one entry per node
            // in index order, for `schema cook-check`
            uint8_t * entry = raw + data_offset + region.bytes;
            table_cook_put( entry, 0, 8, order );
            table_cook_put( entry + 8, 0x3a8fe3852a245245ull, 8, order ); // the root: fnv1a64( "Feed" )
            for ( int64_t k = 0; k < numbering.count; k++ )
            {
                entry += sizeof( TableNodeDirEntry );
                table_cook_put( entry, (uint64_t) region.offsets[k + 1], 8, order );
                table_cook_put( entry + 8, numbering.entries[k].type_id, 8, order );
            }
            // and the HEADER (§7.1), every word a u64 in the order the file is
            // produced in; the two RESERVED words are the memset's zeros
            if ( ok )
            {
                table_cook_put( raw + 0, TableCookMagic, 8, order );
                table_cook_put( raw + 8, BuildVersion, 8, order );
                table_cook_put( raw + 16, (uint64_t) ( order == TableByteOrder::Big ? 2 : 1 ), 8, order );
                table_cook_put( raw + 24, (uint64_t) region.bytes, 8, order );
                table_cook_put( raw + 32, (uint64_t) attribution, 8, order );
                table_cook_put( raw + 40, (uint64_t) region.align, 8, order );
            }
        }
    }
    allocator.free( allocator.context, region.offsets );
    TableNumberingShutdown( numbering );
    return ok;
}

// FeedCookMeasure / FeedCook over a REGION root — a locked builder's AsConst, a
// region FeedLoad produced, or an opened cook — with the pair the numbering
// allocates through as an optional last argument, as the wire's own entries
// take it (§13.9).
inline int64_t FeedCookMeasure( const Feed * root, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return -1; }
    TableRegionCtx ctx;
    return FeedCookMeasureFrom( ctx, *root, allocator );
}

inline bool FeedCook( const Feed * root, void * out, uint64_t capacity, TableByteOrder order, TableAllocator allocator = TableDefaultAllocator() )
{
    if ( root == NULL ) { return false; }
    TableRegionCtx ctx;
    return FeedCookFrom( ctx, *root, out, capacity, order, allocator );
}

// and over a BUILDER, locked or not: the builder's own pair, and the arena
// encoding while it is still mutable (§6.3).
inline int64_t FeedCookMeasure( const FeedBuilder & builder )
{
    if ( builder.region != NULL ) { return FeedCookMeasure( builder.AsConst(), builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return -1; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedCookMeasureFrom( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), builder.arena.allocator );
}

inline bool FeedCook( const FeedBuilder & builder, void * out, uint64_t capacity, TableByteOrder order )
{
    if ( builder.region != NULL ) { return FeedCook( builder.AsConst(), out, capacity, order, builder.arena.allocator ); }
    if ( builder.root_ref.null() ) { return false; } // the root allocation failed
    TableArenaCtx ctx = { &builder.arena };
    return FeedCookFrom( ctx, *(const Feed *) TableArenaAt( builder.arena, (uint32_t) builder.root_ref.value ), out, capacity, order, builder.arena.allocator );
}

// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
// A pointer FIELD is a TableRef — eight bytes and no address — so the
// property holds in BOTH forms: a fixed-size table is one relocatable
// struct, and a packed region is one relocatable block whose references
// are self-relative and therefore survive a plain memcpy.
static_assert( __is_trivially_copyable( Header ), "Header must stay relocatable" );
static_assert( __is_standard_layout( Header ), "Header must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Chunk ), "Chunk must stay relocatable" );
static_assert( __is_standard_layout( Chunk ), "Chunk must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( Feed ), "Feed must stay relocatable" );
static_assert( __is_standard_layout( Feed ), "Feed must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( Header ) == 24, "Header's sizeof moved: the build version was taken over 24, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Header ) == 4, "Header's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Header, name ) == 0, "Header's field name moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Chunk ) == 48, "Chunk's sizeof moved: the build version was taken over 48, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Chunk ) == 8, "Chunk's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, data ) == 0, "Chunk's field data moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, next ) == 16, "Chunk's field next moved: the build version was taken over offset 16 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Chunk, links ) == 24, "Chunk's field links moved: the build version was taken over offset 24 (docs/SPEC-TABLES.md §20.3)" );
static_assert( sizeof( Feed ) == 120, "Feed's sizeof moved: the build version was taken over 120, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( Feed ) == 8, "Feed's alignof moved: the build version was taken over 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, id ) == 0, "Feed's field id moved: the build version was taken over offset 0 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, frame ) == 8, "Feed's field frame moved: the build version was taken over offset 8 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, parts ) == 64, "Feed's field parts moved: the build version was taken over offset 64 (docs/SPEC-TABLES.md §20.3)" );
static_assert( offsetof( Feed, pair ) == 104, "Feed's field pair moved: the build version was taken over offset 104 (docs/SPEC-TABLES.md §20.3)" );

// ---- reflection descriptors (tables only, docs/SPEC-TABLES.md) ----

inline const TableTypeInfo * HeaderTableType();
inline const TableTypeInfo * ChunkTableType();
inline const TableTypeInfo * FeedTableType();
// The descriptors are CONSTANT-INITIALISED data, and a field's target is
// the ADDRESS of another descriptor. These declarations are what let a
// self- or mutually-referential graph — Node naming itself through *Node —
// be expressed as constant data instead of a lazy link, which could not
// have been written race-free OR recursion-safe. The whole reflection
// surface is therefore immutable: read it from any thread, any time.
extern const TableTypeInfo HeaderTableInfo;
extern const TableTypeInfo ChunkTableInfo;
extern const TableTypeInfo FeedTableInfo;

inline const TableFieldInfo HeaderTableFields[] = {
    { "name", "name", "string", 0x30df, 12, false, false, NULL, NULL, true, false, 16, (uint32_t) offsetof( Header, name ), (uint32_t) sizeof( Header::name ), (uint32_t) offsetof( Header, name_length ), 0xffffffffu, NULL, false, 0.0, 0.0, 0, NULL, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
};
inline const TableTypeInfo HeaderTableInfo = { "Header", (uint32_t) sizeof( Header ), 1, HeaderTableFields, +[]( void * p ) { HeaderReset( *(Header *) p ); }, false };
inline const TableTypeInfo * HeaderTableType() { return &HeaderTableInfo; }

inline const TableFieldInfo ChunkTableFields[] = {
    { "data", "data", "bytes", 0x3ad7, 6, true, false, NULL, NULL, true, false, 8, (uint32_t) offsetof( Chunk, data ), (uint32_t) sizeof( Chunk::data[0] ), (uint32_t) offsetof( Chunk, data_length ), 0xffffffffu, NULL, false, 0.0, 0.0, 0, NULL, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
    { "next", "next", "Chunk", 0xd15e, 17, false, true, []( const void * slot ) -> const void * { return (const void *) ChunkAt( *(const TableRef *) slot ); }, []( TableWorker & worker, void * slot ) -> void * { return (void *) ChunkEmplace( worker, *(TableRef *) slot ); }, false, false, 0, (uint32_t) offsetof( Chunk, next ), (uint32_t) sizeof( TableRef ), 0xffffffffu, 0xffffffffu, &ChunkTableInfo, false, 0.0, 0.0, 0, NULL, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
    { "links", "links", "Chunk", 0x7324, 17, true, true, []( const void * slot ) -> const void * { return (const void *) ChunkAt( *(const TableRef *) slot ); }, []( TableWorker & worker, void * slot ) -> void * { return (void *) ChunkEmplace( worker, *(TableRef *) slot ); }, true, false, 2, (uint32_t) offsetof( Chunk, links ), (uint32_t) sizeof( Chunk::links[0] ), (uint32_t) offsetof( Chunk, links_count ), 0xffffffffu, &ChunkTableInfo, false, 0.0, 0.0, 0, NULL, -1, NULL, NULL, NULL, NULL, NULL, NULL, "" },
};
